  // ── The opening stretch of the curriculum ───────────────────────────────
  // The words a learner meets in their first months: the function words the
  // sentences are built from, the core verbs, and the nouns and adjectives
  // the everyday packs lean on. Written against the German cards' own
  // glosses, so that laut is the adjective the pack teaches and not the
  // preposition, and Kater is the hangover rather than the cat.
  // ── Core function words and connectors ──────────────────────────────────
  "und": "e",
  "oder": "ou",
  "aber": "mas",
  "denn": "pois",
  "weil": "porque",
  "dass": "que",
  "wenn": "se",
  "als": "quando",
  "obwohl": "embora",
  "damit": "para que",
  "trotzdem": "mesmo assim",
  "deshalb": "por isso",
  "deswegen": "por essa razão",
  "außerdem": "além disso",
  "jedoch": "contudo",
  "sondern": "mas sim",
  "also": "portanto",
  "zwar": "é certo que",
  "sowie": "bem como",
  "falls": "caso",
  "sobald": "assim que",
  "solange": "enquanto",
  "seitdem": "desde então",
  // The preposition, which is what the pack teaches; as a conjunction it is
  // enquanto, which solange already has.
  "während": "durante",
  "bevor": "antes de",
  "nachdem": "depois de",
  "bis": "até",
  "ohne": "sem",
  "statt": "em vez de",
  "wegen": "por causa de",
  "trotz": "apesar de",
  // Formal, and it stays formal: the everyday equivalent is de acordo com.
  "gemäß": "em conformidade com",
  "sonst": "senão",
  // entweder/oder is ou/ou in Portuguese, so the first half lands on the same
  // word as oder. One word is the truth about the language.
  "entweder": "ou",
  "weder": "nem",
  "sowohl": "tanto",
  "je": "quanto",
  "desto": "tanto",
  "zum Beispiel": "por exemplo",
  "und so weiter": "e assim por diante",
  "vor allem": "sobretudo",
  "im Gegenteil": "pelo contrário",
  "auf jeden Fall": "sem falta",
  "auf keinen Fall": "de maneira nenhuma",
  "zum Glück": "felizmente",
  "leider": "infelizmente",

