  "welcher": "qual",
  "welche": "qual",
  "welches": "qual",
  "wie viel": "quanto",
  "wie viele": "quantos",
  "wie lange": "quanto tempo",
  "wie oft": "com que frequência",
  "wofür": "para quê",
  "womit": "com quê",
  // The qualifying afterthought, not the relative adverb.
  "wobei": "sendo que",
  "wozu": "para quê",

