  // ── I can do it: ability and encouragement (part150) ────────────────────
  // German leans on können for all of this; Portuguese splits it. Poder is
  // permission and possibility, conseguir is managing the thing, and ser
  // capaz is believing you have it in you. Rendering all three as poder is
  // the single fastest way to sound translated.
  "Ich kann das.": "Eu consigo fazer isso.",
  "Du kannst das.": "Tu consegues.",
  "Wir können das.": "Nós conseguimos.",
  "Ihr könnt das.": "Vocês conseguem.",
  "Kannst du das?": "Consegues fazer isso?",
