  "Nein, das kann ich noch nicht.": "Não, ainda não consigo.",
  "Ich kann das selbst machen.": "Consigo fazer isso sozinho.",
  "Du kannst das selbst machen.": "Tu consegues fazer isso sozinho.",
  "Wir können es zusammen machen.": "Podemos fazer isso juntos.",
  "Ich kann dir helfen.": "Posso ajudar-te.",
  "Du kannst mich jederzeit fragen.": "Podes perguntar-me sempre que quiseres.",
  "Wir können es zusammen versuchen.": "Podemos tentar juntos.",
  "Noch kann ich das nicht.": "Isso ainda não consigo.",
  "Ich kann das inzwischen ganz gut.": "Já faço isso bastante bem.",
  "Ich weiß, dass ich das kann.": "Sei que sou capaz.",
  "Ich glaube, dass du das kannst.": "Acredito que tu és capaz.",
  "Ich schaffe das.": "Eu vou conseguir.",
  "Das schaffen wir.": "Nós vamos conseguir.",
  "Ich traue mir das zu.": "Sinto-me capaz disso.",
  "Ich traue dir das zu.": "Acho-te capaz disso.",
  "Du packst das.": "Tu dás conta disso.",
  "Du musst es nicht sofort können.": "Não tens de saber fazer isso logo à primeira.",
