  "Ich helfe dir, wenn du nicht weiterkommst.": "Ajudo-te se não conseguires avançar.",
  // "einfach" is not a word here, it is a shrug. Portuguese does the same job
  // with "só" before the verb.
  "Wir probieren es einfach noch einmal.": "Vamos só tentar outra vez.",
  "Wir geben nicht auf.": "Não vamos desistir.",
  "Wir müssen nicht alles auf einmal schaffen.": "Não temos de fazer tudo de uma vez.",
  "Es wird jedes Mal ein bisschen leichter.": "De cada vez fica um bocadinho mais fácil.",
  "Ich bin noch nicht fertig, aber ich komme voran.": "Ainda não acabei, mas estou a avançar.",
  "Ich kann das schon allein.": "Já consigo fazer isso sozinho.",
  // Ser canja — to be chicken soup — is what Portuguese says for something
  // that will cost you nothing.
  "Das schaffst du locker.": "Isso para ti é canja.",
  // "mal" softens the imperative into an invitation, and the Portuguese "lá"
  // does exactly that and nothing else.
  "Probier es einfach mal.": "Experimenta lá.",
  "Schau her, ich zeige es dir.": "Olha, eu mostro-te.",
  "Beim ersten Mal klappt das selten.": "À primeira raramente resulta.",
  "Noch einmal, diesmal etwas langsamer.": "Outra vez, desta vez um pouco mais devagar.",
  "Ich traue mich noch nicht.": "Ainda não me atrevo.",
  // The "doch" is the whole line: it worked after all, against expectation.
  // Portuguese carries that in "afinal".
  "Siehst du? Es geht doch!": "Estás a ver? Afinal sempre dá!",
  "Traust du dir das allein zu?": "Achas que dás conta sozinho?",
  "Ich versuche es erst einmal selbst.": "Primeiro vou tentar sozinho.",
  "Ruf mich, wenn du Hilfe brauchst.": "Chama-me se precisares de ajuda.",
  "Mach ich. Danke dir.": "Combinado. Obrigado.",
  "Wie weit bist du gekommen?": "Até onde é que chegaste?",
  "Den ersten Teil habe ich geschafft.": "A primeira parte já consegui.",
