  "Und wie sieht's bei dir aus?": "E do teu lado, como é que vai?",
  "Meld dich, wenn du Zeit hast.": "Diz alguma coisa quando tiveres tempo.",
  "Schreib mir einfach.": "Manda-me só uma mensagem.",
  "Bin gleich zurück.": "Volto já.",
  "Ich komme gleich wieder.": "Volto num instante.",
  "Ich bin ein bisschen spät dran.": "Estou um bocadinho atrasado.",
  "Ich komme etwas später.": "Chego um pouco mais tarde.",
  "Ich muss jetzt los.": "Tenho de ir andando.",
  "Ich ruf dich später an.": "Ligo-te mais tarde.",
  "Sag Bescheid, falls sich was ändert.": "Avisa se alguma coisa mudar.",
  "Kein Problem, lass dir Zeit.": "Não há problema, leva o tempo que precisares.",
  "Keine Eile.": "Não há pressa.",
