  "Ich komme mit.": "Eu vou contigo.",
  "Wollen wir los?": "Vamos andando?",
  "Mach dir keinen Kopf.": "Não te preocupes com isso.",
  "Das klären wir später.": "Isso resolvemos depois.",
  "Wir sprechen später darüber.": "Falamos disso mais tarde.",
  "Ich melde mich morgen.": "Dou notícias amanhã.",
  "Passt es dir am Freitag?": "Na sexta dá-te jeito?",
  "Freitag passt mir super.": "Sexta dá-me imenso jeito.",
  "Ich melde mich morgen bei dir.": "Amanhã entro em contacto contigo.",
  "Wollen wir uns um vier treffen?": "Encontramo-nos às quatro?",
  "Ich schaffe es heute leider nicht.": "Hoje não vou conseguir, infelizmente.",
  "Klappt es bei dir am Wochenende?": "Ao fim de semana consegues?",
  "Bis wann bist du im Büro?": "Até que horas estás no escritório?",
  "Dann sage ich einfach kurz Bescheid.": "Então é só eu avisar.",
  "Lange nicht gesehen!": "Há quanto tempo!",
  "Schön, dich zu sehen. Wie war dein Wochenende?": "Que bom ver-te. Como foi o teu fim de semana?",
