  "Bringst du morgen die Unterlagen mit?": "Trazes os documentos amanhã?",
  "Mache ich. Jetzt aber wirklich, tschüss!": "Trago. Agora é mesmo a sério, adeus!",
  "Wollen wir morgen etwas essen gehen?": "Vamos comer fora amanhã?",
