  "Mache ich gleich.": "Faço isso já.",
  "Danke. Ich freue mich schon.": "Obrigado. Já estou ansioso.",

  // ── Choices, turns, repair and boundaries (part161) ─────────────────────
  "die Absicht": "a intenção",
  "jemanden ausreden lassen": "deixar alguém acabar de falar",
  "passieren": "acontecer",
  "Schwer zu sagen.": "Difícil dizer.",
  "Kann ich nicht sagen.": "Isso não te sei dizer.",
  "Ich glaube schon.": "Creio que sim.",
  "Ich glaube eher nicht.": "Acho que não.",
  "Warum nicht?": "Porque não?",
  "Mir ist beides recht.": "Por mim, tanto faz.",
  "Du entscheidest.": "Tu é que decides.",
  "Such du aus.": "Escolhe tu.",
  "Das ist mir lieber.": "Prefiro assim.",
  "Ich denk noch drüber nach.": "Ainda estou a pensar nisso.",
  "Kann ich dich kurz sprechen?": "Posso falar contigo um bocadinho?",
  "Hast du einen Moment?": "Tens um momento?",
