  "Ich hab das nicht so gemeint.": "Não foi isso que eu quis dizer.",
  "Das war keine Absicht.": "Não foi de propósito.",
  "Ich hab's vergessen.": "Esqueci-me.",
  "Kommt nicht wieder vor.": "Não volta a acontecer.",
  "Kann passieren.": "São coisas que acontecem.",
  "Mach dir nichts draus.": "Não ligues a isso.",
  "Das hört sich echt anstrengend an.": "Isso parece mesmo cansativo.",
