  "Mittlerweile mache ich das seltener.": "Hoje em dia faço isso menos vezes.",
  "In letzter Zeit mache ich das wieder öfter.": "Ultimamente voltei a fazer isso mais vezes.",
  "Ich versuche, das jeden Tag zu machen.": "Tento fazer isso todos os dias.",
  "Ich will mir das angewöhnen.": "Quero ganhar esse hábito.",
  "Ich möchte mir das abgewöhnen.": "Quero perder esse hábito.",
  "Ich bin noch nicht daran gewöhnt.": "Ainda não me habituei.",
  "Langsam wird es zur Gewohnheit.": "Aos poucos está a tornar-se um hábito.",
  "Ich habe meine Routine geändert.": "Mudei a minha rotina.",
  "Seit Kurzem mache ich das anders.": "Há pouco tempo comecei a fazer isso de outra maneira.",
  "Ich vergesse das ständig.": "Esqueço-me disso constantemente.",
  "Das passiert mir immer wieder.": "Isso acontece-me vezes sem conta.",
