  "Das ist bei mir ganz normal.": "Para mim isso é perfeitamente normal.",
  "Das gehört für mich einfach dazu.": "Para mim isso faz parte.",
  "Ohne das starte ich nicht in den Tag.": "Sem isso não começo o dia.",
  "Ich halte mich nicht immer daran.": "Nem sempre cumpro.",
  "Ich versuche, konsequent zu bleiben.": "Tento manter-me firme.",
  "Heute mache ich mal eine Ausnahme.": "Hoje abro uma exceção.",
  "Das ist jede Woche anders.": "Cada semana é diferente.",
