  "Sonntags schlafen wir lange.": "Aos domingos dormimos até tarde.",
  "Normalerweise koche ich selbst.": "Normalmente cozinho eu.",
  "Zweimal pro Woche gehe ich schwimmen.": "Vou nadar duas vezes por semana.",
  "Ich esse fast nie Fleisch.": "Quase nunca como carne.",
  "Ab und zu gönne ich mir ein Eis.": "De vez em quando dou-me ao luxo de um gelado.",
  // Not "nada funciona sem café" — the Portuguese joke is that you are not
