  "Ohne Kaffee geht bei mir gar nichts.": "Sem café não sou pessoa.",
  "Meistens bin ich vor sieben wach.": "Quase sempre estou acordado antes das sete.",
  "Und am Wochenende?": "E ao fim de semana?",
