  "Erst seit Kurzem.": "Só há pouco tempo.",
  "Hast du dich schon daran gewöhnt?": "Já te habituaste?",
  "Noch nicht ganz, aber langsam wird es zur Gewohnheit.": "Ainda não completamente, mas aos poucos está a tornar-se um hábito.",

  // ── Finding, borrowing, sharing, putting away (part166) ─────────────────
  // Portuguese throws things fora rather than away, fetches by going to get
  // them — ir buscar — and asks politely with se faz favor, which is what
  // the everyday bitte is. Por favor is not wrong; se faz favor is what is
  // said across a kitchen.
  "sich etwas ausleihen": "pedir alguma coisa emprestada",
  "jemandem etwas leihen": "emprestar alguma coisa a alguém",
  "übrig sein": "sobrar",
  "Wo ist mein Handy?": "Onde está o meu telemóvel?",
  "Ich kann meine Schlüssel nicht finden.": "Não encontro as minhas chaves.",
  "Wo hab ich das hingelegt?": "Onde é que eu pus isto?",
  "Ich weiß nicht mehr, wo ich es hingelegt habe.": "Já não me lembro onde é que o pus.",
  "Es muss hier irgendwo sein.": "Tem de estar aqui algures.",
  "Suchst du das hier?": "É isto que procuras?",
  "Da ist es ja!": "Ah, está aqui!",
  "Ich hab's gefunden.": "Já encontrei.",
  "Das liegt da drüben.": "Está ali.",
  "Schau mal in der Schublade nach.": "Vê lá na gaveta.",
  "Ist das deins?": "Isto é teu?",
  "Gehört das vielleicht dir?": "Isto por acaso é teu?",
  "Kann ich mir das kurz ausleihen?": "Posso pedir isso emprestado um bocadinho?",
