  "Du kannst es bis morgen behalten.": "Podes ficar com ele até amanhã.",
  "Pass bitte gut darauf auf.": "Tem cuidado com ele, se faz favor.",
  "Danke, ich bringe es dir zurück.": "Obrigado, depois trago-to de volta.",
