  "Lass mir bitte noch etwas übrig.": "Deixa-me alguma coisa, se faz favor.",
  "Denk bitte daran, das mitzubringen.": "Não te esqueças de trazer isso.",
  "Vergiss deine Schlüssel nicht.": "Não te esqueças das chaves.",
  "Ich hab's zu Hause liegen lassen.": "Deixei ficar em casa.",
  "Ich hole es schnell.": "Vou já buscá-lo.",
  "Ich bringe es dir später vorbei.": "Depois passo por aí e levo-to.",
  "Kannst du das für mich mitnehmen?": "Podes levar isso por mim?",
  "Lass das ruhig hier.": "Deixa isso aqui à vontade.",
  "Ich nehme es gleich mit.": "Levo-o já comigo.",
  "Hast du an alles gedacht?": "Não te esqueceste de nada?",
  "Mir fehlt nur noch mein Ladegerät.": "Só me falta o carregador.",
  "Wo kommt das hin?": "Onde é que isto vai?",
  "Wo soll ich das hinlegen?": "Onde é que ponho isto?",
  "Leg es einfach auf den Tisch.": "Põe isso em cima da mesa.",
  "Stell das bitte ins Regal.": "Põe isso na estante, se faz favor.",
  "Kannst du das kurz wegräumen?": "Podes arrumar isso num instante?",
