  "Meinst du den hier?": "Queres dizer este?",
  "Nein, den anderen.": "Não, o outro.",
  "Ja, genau den.": "Sim, esse mesmo.",
  "Welche davon gefällt dir besser?": "De qual é que gostas mais?",
  "Ich nehme lieber den hier.": "Prefiro levar este.",
