  // ── Everyday amounts: enough, too much, sharing (part168) ───────────────
  // Reichen is chegar, which is the same verb as arriving: enough is what
  // gets there. Chega e sobra for plenty, ir a meias for splitting it, and
  // que chegue where German says genug — all of them ordinary and none of
  // them a rendering of suficiente.
  "Wie viel brauchst du?": "De quanto é que precisas?",
  "Wie viele brauchen wir?": "Quantos é que precisamos?",
  "Wie viel davon soll ich nehmen?": "Quanto é que levo disso?",
  "Wie viel möchtest du?": "Quanto é que queres?",
  "Reicht das für alle?": "Isso chega para todos?",
  "Brauchen wir noch mehr?": "Precisamos de mais?",
  "Wie viel ist noch da?": "Quanto é que ainda há?",
  "Wie viele sind noch übrig?": "Quantos é que ainda sobram?",
  "Ist noch genug da?": "Ainda há que chegue?",
  "Was meinst du, wie viel brauchen wir?": "De quanto é que achas que precisamos?",
  "Das reicht völlig.": "Isso chega e sobra.",
  "Das müsste reichen.": "Isso deve chegar.",
  "Das reicht noch nicht.": "Isso ainda não chega.",
  "Das ist zu viel.": "Isso é demasiado.",
  "Das ist ein bisschen zu wenig.": "Isso é um bocadinho pouco.",
  "Nicht so viel, bitte.": "Não tanto, se faz favor.",
  "Nur ein bisschen.": "Só um bocadinho.",
  "Noch ein kleines bisschen.": "Mais um nadinha.",
  "Mehr brauche ich nicht.": "Mais não preciso.",
  "Ich habe genug, danke.": "Já tenho que chegue, obrigado.",
  "Es ist fast nichts mehr da.": "Já quase não há nada.",
  "Davon ist noch genug da.": "Disso ainda há que chegue.",
  "Wir haben nur noch zwei.": "Só temos mais dois.",
  "Das war der letzte.": "Esse era o último.",
  "Nimm den Rest mit.": "Leva o resto.",
  "Lass bitte etwas für die anderen übrig.": "Deixa alguma coisa para os outros, se faz favor.",
  "Ist noch etwas übrig?": "Ainda sobrou alguma coisa?",
  "Es ist alles weg.": "Já não há nada.",
  "Wir müssen bald Nachschub holen.": "Temos de ir buscar mais em breve.",
