  "Nimm dir ruhig noch etwas.": "Serve-te de mais à vontade.",
  "Möchtest du die Hälfte?": "Queres metade?",
  "Ich gebe dir etwas davon ab.": "Dou-te um bocado do meu.",
  "Wir können den Rest aufteilen.": "Podemos repartir o resto.",
  "Das ist für uns beide.": "Isso é para nós os dois.",
  "Heb mir bitte etwas auf.": "Guarda-me um bocado, se faz favor.",
  "Ungefähr die Hälfte.": "Mais ou menos metade.",
  "Etwa doppelt so viel.": "Cerca do dobro.",
  "Ein bisschen weniger.": "Um bocadinho menos.",
  "Mach ruhig etwas mehr.": "Faz mais um bocado à vontade.",
  "Das sind ungefähr zehn.": "São uns dez.",
  "So viel brauchen wir nicht.": "Não precisamos de tanto.",
  "Lieber etwas zu viel als zu wenig.": "Antes a mais do que a menos.",
