  // ── Thinking, knowing, remembering, checking (part169) ──────────────────
  // Portuguese does not remember things, things occur to it: ocorrer for the
  // word that will not come, lembrar-se for what is held. And the shrug of
  // not knowing is sei lá, one syllable more than a shrug and doing the same
  // work as the whole German rhetorical question.
  "Ich glaube, wir haben genug.": "Acho que temos que chegue.",
  "Ich glaube, das war alles.": "Acho que era tudo.",
  "Ich denke, wir sollten langsam gehen.": "Acho que devíamos ir andando.",
  "Ich denke noch darüber nach.": "Ainda estou a pensar no assunto.",
  "Ich muss erst mal darüber nachdenken.": "Primeiro tenho de pensar bem nisso.",
  "Da muss ich kurz überlegen.": "Deixa-me pensar um bocadinho.",
  "Für mich klingt das gut.": "A mim parece-me bem.",
  "So sehe ich das auch.": "Também vejo isso assim.",
  "Ich sehe das etwas anders.": "Eu vejo isso um pouco de outra maneira.",
  "Wie würdest du das einschätzen?": "Como é que tu avalias isso?",
