  "Das wusste ich gar nicht.": "Isso eu não fazia ideia.",
  "Jetzt weiß ich Bescheid.": "Agora já estou a par.",
  "Damit kenne ich mich nicht aus.": "Disso não percebo nada.",
  "Der Name sagt mir nichts.": "Esse nome não me diz nada.",
  "Ich weiß es gerade nicht mehr.": "Agora não me está a ocorrer.",
  "So genau kann ich dir das nicht sagen.": "Ao certo não te sei dizer.",
  "Weißt du noch, wie das hieß?": "Ainda te lembras de como se chamava?",
  "Ah, jetzt weiß ich es wieder.": "Ah, agora já sei.",
  "Ich kann mich gerade nicht erinnern.": "Neste momento não me lembro.",
  "Ich hab's völlig vergessen.": "Esqueci-me completamente.",
