  "Der Teig muss eine Stunde gehen.": "A massa tem de levedar uma hora.",
  "Knete den Teig, bis er nicht mehr klebt.": "Amassa até deixar de pegar às mãos.",
  "Verrühr die Eier mit dem Schneebesen.": "Bate os ovos com o batedor.",
  "Beim Backen muss man genau abwiegen.": "Na pastelaria é preciso pesar tudo com rigor.",
  "Mist, das Ganze ist mir angebrannt.": "Bolas, agarrou-me tudo ao fundo.",
  "Mir ist die Soße zu dünn geraten.": "O molho saiu-me demasiado líquido.",
  "Dann lass sie noch etwas einkochen.": "Então deixa-o reduzir mais um bocado.",
  "Lass es kurz abkühlen, bevor du probierst.": "Deixa arrefecer um bocado antes de provares.",
  "Vorsicht, der Topf ist heiß.": "Cuidado, a panela está a escaldar.",
  "Das riecht aber gut, was kochst du?": "Isso cheira mesmo bem, o que estás a cozinhar?",
  "Deck schon mal den Tisch, es ist gleich fertig.": "Vai pondo a mesa, está quase pronto.",
  "Ich habe die doppelte Menge gemacht, der Rest wird eingefroren.": "Fiz o dobro, o resto vai para o congelador.",
  "Selbst gekocht schmeckt es doch am besten.": "Feito em casa sabe sempre melhor.",
  "Was fehlt noch für das Curry?": "O que é que ainda falta para o caril?",
  "Schäl schon mal die Zwiebeln, ich mache den Reis.": "Vai descascando as cebolas, eu faço o arroz.",
