  "Haben Sie am Wochenende noch etwas verfügbar?": "Tem alguma coisa disponível para o fim de semana?",
  "Ist das Frühstück im Preis inklusive?": "O pequeno-almoço está incluído no preço?",
  "Wir nehmen Halbpension, dann sind wir beim Mittagessen flexibel.": "Ficamos com meia pensão, assim estamos livres ao almoço.",
  "Gibt es Zimmer mit Meerblick? — Gegen Aufpreis, ja.": "Há quartos com vista para o mar? — Com suplemento, há.",
  "Bis wann kann ich kostenlos stornieren?": "Até quando posso cancelar sem custos?",
  "Die Anzahlung wird bei der Buchung fällig.": "O sinal é pago no momento da reserva.",
  "Ich habe die Bestätigung per Mail bekommen.": "Recebi a confirmação por e-mail.",
  "Wir haben reserviert, auf den Namen Weber.": "Temos reserva, em nome de Weber.",
  "Der Check-in ist ab fünfzehn Uhr.": "O check-in é a partir das três da tarde.",
  "Können wir das Gepäck schon mal abstellen?": "Podemos deixar já a bagagem?",
  "Hier ist Ihre Schlüsselkarte, Zimmer zweihundertvier.": "Aqui está o cartão do quarto, quarto duzentos e quatro.",
  "Der Aufzug ist gleich um die Ecke.": "O elevador é já ali à esquina.",
  "Wann gibt es Frühstück? — Von sieben bis halb elf.": "A que horas é o pequeno-almoço? — Das sete às dez e meia.",
  "Das Frühstücksbuffet lohnt sich, geh früh runter.": "O bufete vale a pena, desce cedo.",
  "Die Klimaanlage bekomme ich nicht leiser.": "Não consigo pôr o ar condicionado mais baixo.",
  "Unser Zimmer geht zur Straße raus, es ist ziemlich laut.": "O nosso quarto dá para a rua, é bastante barulhento.",
  "Können wir noch ein Kissen extra bekommen?": "Podíamos ter mais uma almofada?",
  "Das WLAN-Passwort steht auf der Karte an der Rezeption.": "A palavra-passe da wi-fi está no cartão da receção.",
  "Bitte machen Sie das Zimmer erst nach zehn Uhr.": "Façam o quarto só depois das dez, se faz favor.",
  "Die Minibar haben wir nicht angerührt.": "Não tocámos no minibar.",
  "Wir bleiben eine Nacht länger, geht das?": "Ficamos mais uma noite, é possível?",
  "Bis wann müssen wir auschecken? — Bis elf.": "Até que horas temos de fazer o check-out? — Até às onze.",
  "Können wir spät auschecken? Unser Zug fährt erst am Nachmittag.": "Podemos fazer check-out mais tarde? O nosso comboio só parte à tarde.",
  "Können Sie uns ein Taxi zum Bahnhof bestellen?": "Pode chamar-nos um táxi para a estação?",
  "Eine Übernachtung mit Frühstück kostet neunzig Euro.": "Uma dormida com pequeno-almoço custa noventa euros.",
  "Der Aufenthalt war wunderbar, wir kommen wieder.": "A estadia foi maravilhosa, havemos de voltar.",
  "Beim nächsten Mal bleiben wir länger.": "Da próxima vez ficamos mais tempo.",
  "Guten Abend, wir haben ein Doppelzimmer reserviert.": "Boa noite, temos um quarto duplo reservado.",
  "Auf welchen Namen, bitte?": "Em que nome, se faz favor?",
