  "Etwas zum Hof wäre wunderbar.": "Alguma coisa para o pátio era ótimo.",
  "Zimmer einundzwanzig ist ruhig — ich buche Sie um.": "O quarto vinte e um é sossegado — vou alterar a vossa reserva.",

  // ── Ill at home (part192) ───────────────────────────────────────────────
  // Hühnersuppe is a canja, which is the same soup and the same gesture —
  // what somebody makes for you when you are ill. Gute Besserung is as
  // melhoras, an illness is pegada rather than passed on, and being bunged
  // up is being constipado, the word this table has already had to be
  // careful with.
  "sich auskurieren": "restabelecer-se",
  "die Salbe": "a pomada",
  "das Nasenspray": "o spray nasal",
  "verschnupft": "constipado",
  "gurgeln": "gargarejar",
  "die Hühnersuppe": "a canja",
  "das Fieberthermometer": "o termómetro",
  "abklingen": "abrandar",
  "einnehmen": "tomar",
  "sich hinlegen": "deitar-se",
  "die Bettruhe": "o repouso na cama",
  "schwitzen": "suar",
  "der Kräutertee": "o chá de ervas",
  "der Hustensaft": "o xarope para a tosse",
  "die Besserung": "as melhoras",
  "Mich hat es jetzt auch erwischt.": "Agora também me apanhou.",
  "Ich bin total verschnupft, ich kriege kaum Luft.": "Estou completamente constipado, mal consigo respirar.",
  "Meine Nase läuft ununterbrochen.": "O nariz não para de me pingar.",
  "Miss mal Fieber, du glühst ja richtig.": "Mede lá a febre, estás mesmo a arder.",
  "Achtunddreißig fünf — das ist erhöhte Temperatur.": "Trinta e oito e cinco — isso é febre.",
  "Ich rieche und schmecke gerade gar nichts.": "Neste momento não cheiro nem sinto o sabor a nada.",
  "Bleib heute im Bett, du musst das richtig auskurieren.": "Hoje fica na cama, tens de te restabelecer como deve ser.",
  "Verschlepp die Erkältung nicht, sonst dauert es Wochen.": "Não arrastes a constipação, senão dura semanas.",
  "Der Arzt hat mir strenge Bettruhe verordnet.": "O médico receitou-me repouso absoluto na cama.",
  "Ich lege mich mal eine Stunde hin.": "Vou deitar-me uma hora.",
  "Nimm den Hustensaft dreimal täglich ein.": "Toma o xarope três vezes por dia.",
  "Die Tropfen musst du vor dem Essen einnehmen.": "As gotas tens de as tomar antes das refeições.",
  "Das Nasenspray nicht länger als eine Woche benutzen.": "O spray nasal não se usa mais de uma semana.",
  "Die Salbe reibst du abends auf die Brust.": "A pomada esfregas no peito à noite.",
  "Komm mir nicht zu nah, ich will dich nicht anstecken.": "Não te chegues muito, não te quero pegar isto.",
  "Gurgeln mit Salzwasser hilft gegen Halsschmerzen.": "Gargarejar com água salgada ajuda contra as dores de garganta.",
  "Ich mache dir eine Hühnersuppe, die hilft immer.": "Faço-te uma canja, isso ajuda sempre.",
  "Ein Kräutertee mit Honig, und dann ab ins Bett.": "Um chá de ervas com mel, e depois para a cama.",
  "Ich habe die ganze Nacht geschwitzt.": "Suei a noite toda.",
  "Dann war das Fieber am Morgen zum Glück weg.": "Felizmente de manhã a febre já tinha passado.",
  "Trink viel und schlaf dich richtig aus.": "Bebe muito e dorme bem.",
  "Der Husten klingt langsam ab.": "A tosse está aos poucos a abrandar.",
  "Ich bin noch nicht ganz auf dem Damm.": "Ainda não estou totalmente restabelecido.",
  "Kurier dich lieber ein paar Tage länger aus.": "Antes fica mais uns dias a restabelecer-te.",
  "Zum Glück war es nur eine leichte Erkältung.": "Felizmente era só uma constipação ligeira.",
  "Ich fühle mich schon viel besser als gestern.": "Já me sinto muito melhor do que ontem.",
  "Gute Besserung, kurier dich richtig aus!": "As melhoras, restabelece-te como deve ser!",
  "Ab morgen bin ich wieder einsatzbereit.": "A partir de amanhã já estou operacional.",
  "Du klingst furchtbar. Leg dich wieder hin.": "A tua voz está péssima. Volta a deitar-te.",
  "Ich wollte nur kurz Tee holen.": "Só queria ir buscar chá.",
  "Ich bringe ihn dir. Hast du Fieber gemessen?": "Eu levo-to. Já mediste a febre?",
  "Achtunddreißig zwei. Es geht schon wieder etwas besser.": "Trinta e oito e dois. Já estou um bocado melhor.",
  "Na, wie geht es dir heute?": "Então, como te sentes hoje?",
  "Besser. Das Fieber ist weg, nur der Husten bleibt.": "Melhor. A febre passou, só fica a tosse.",
  "Kurier dich trotzdem richtig aus.": "Mesmo assim, restabelece-te como deve ser.",
  "Versprochen. Montag bin ich wieder auf dem Damm.": "Prometo. Na segunda já estou bom.",

