  "Auf welcher Station liegt sie denn?": "E ela está em que serviço?",
  "Sie liegt auf Station drei, Zimmer zwölf.": "Está no serviço três, quarto doze.",
  "Am Empfang muss man sich kurz anmelden.": "Na receção é preciso identificar-se.",
  "Ich bringe ihr einen kleinen Blumenstrauß mit.": "Vou levar-lhe um raminho de flores.",
  "Frag vorher, was er im Krankenhaus essen darf.": "Pergunta antes o que é que ele pode comer no hospital.",
  "Brauchst du etwas von zu Hause? Ich bringe es morgen mit.": "Precisas de alguma coisa de casa? Trago amanhã.",
  "Die Operation ist gut verlaufen.": "A operação correu bem.",
  "Der Eingriff war zum Glück kleiner als gedacht.": "Felizmente a intervenção foi mais pequena do que se pensava.",
  "Sie hat die Narkose gut überstanden.": "Ela aguentou bem a anestesia.",
