  "Der Tropf kommt morgen ab, sagt die Ärztin.": "O soro sai amanhã, diz a médica.",
  "Bei der Visite war heute das ganze Team da.": "Hoje na ronda estava a equipa toda.",
  "Die Pflegekräfte hier sind wirklich freundlich.": "Os enfermeiros aqui são mesmo simpáticos.",
  "Im Zweibettzimmer hat sie nette Gesellschaft.": "No quarto de duas camas tem boa companhia.",
  "Das Krankenbett lässt sich elektrisch verstellen — sein Lieblingsspielzeug.": "A cama regula-se eletricamente — é o brinquedo preferido dele.",
