  "Sie ist auf dem Weg der Besserung.": "Está a caminho das melhoras.",
  "Heute durfte sie zum ersten Mal wieder aufstehen.": "Hoje já pôde levantar-se pela primeira vez.",
  "Mit dem Laufen klappt es schon wieder besser.": "A andar já está a correr melhor.",
  "Er wird voraussichtlich am Freitag entlassen.": "Previsivelmente tem alta na sexta.",
  "Nach der Entlassung kommt sie erst mal zu uns.": "Depois da alta vem primeiro para nossa casa.",
  "Zuhause erholt man sich am schnellsten.": "É em casa que se recupera mais depressa.",
