  "die Bedienung": "o empregado de mesa",
  "kassieren": "cobrar",
  "Der Rest ist für Sie.": "O resto é para si.",
  "sich verrechnen": "enganar-se nas contas",
  "Zahlen, bitte!": "A conta, se faz favor!",
  "das Portemonnaie": "a carteira",
