  // ── The lottery: six right, the office pool and the dream (part240) ─────
  //
  // Portugal runs the same game under its own name, and the vocabulary is
  // already there waiting: o boletim, o sorteio, os números sorteados, o
  // número da sorte, which is the Totoloto's extra ball and does exactly what
  // the Superzahl does. Das Rubbellos is a raspadinha — the word is the sound
  // of scratching it, and no Portuguese speaker needs it explained.
  //
  // Trotzdem träumen darf man ja is a shrug, not a permission. Portuguese
  // puts the same shrug in the word order: sonhar, isso ninguém proíbe.
  "der Lottoschein": "o boletim do totoloto",
  "sechs Richtige": "seis certos",
  "der Jackpot": "o jackpot",
  "das Rubbellos": "a raspadinha",
  "die Tippgemeinschaft": "o grupo de apostas",
  "die Annahmestelle": "o posto de apostas",
  "die Gewinnzahlen": "os números sorteados",
  "die Ziehung": "o sorteio",
  "tippen": "apostar",
  "ankreuzen": "marcar com uma cruz",
  "die Superzahl": "o número da sorte",
  "die Quote": "o valor do prémio",
  "der Zufall": "o acaso",
  "der Tipp": "a aposta",
  "der Hauptgewinn": "o primeiro prémio",
  "Samstags gebe ich meinen Lottoschein ab.": "Ao sábado entrego o meu boletim.",
