  "Geburtstage tippen alle — dann teilt man den Gewinn.": "Toda a gente aposta em datas de nascimento — e depois o prémio reparte-se.",
  "Die Annahmestelle ist der Kiosk an der Ecke.": "O posto de apostas é o quiosque da esquina.",
  "Ein Feld kostet etwa einen Euro zwanzig.": "Cada grelha custa cerca de um euro e vinte.",
  "Im Büro haben wir eine Tippgemeinschaft.": "No escritório temos um grupo de apostas.",
  "Zwölf Leute, ein Schein, große Träume.": "Doze pessoas, um boletim, sonhos grandes.",
  "Wenn die Tippgemeinschaft gewinnt, kündigen alle zusammen.": "Se o grupo ganhar, despedimo-nos todos ao mesmo tempo.",
  "Die Ziehung ist samstags um viertel nach sieben.": "O sorteio é ao sábado às sete e um quarto.",
  "Früher lief die Ziehung live im Fernsehen.": "Dantes o sorteio passava em direto na televisão.",
  "Ich vergleiche die Gewinnzahlen erst am Sonntag.": "Só vou ver os números sorteados no domingo.",
  "Drei Richtige — das gibt ungefähr zehn Euro.": "Três certos — dá aí uns dez euros.",
  "Drei Richtige feiern wir trotzdem wie den Jackpot.": "Três certos e festejamos na mesma como se fosse o jackpot.",
  "Sechs Richtige mit Superzahl — das wäre der Hauptgewinn.": "Seis certos com o número da sorte — isso é que era o primeiro prémio.",
  "Der Jackpot liegt diese Woche bei zwanzig Millionen.": "Esta semana o jackpot está nos vinte milhões.",
  "Ab einer bestimmten Summe spielt plötzlich das ganze Land.": "A partir de certo valor, joga o país inteiro.",
  "Die Quote hängt davon ab, wie viele gewonnen haben.": "O valor do prémio depende de quantos acertaram.",
