  "Lotto ist reiner Zufall — jede Zahl ist gleich wahrscheinlich.": "O totoloto é puro acaso — todos os números têm a mesma probabilidade.",
  "Die Chance auf den Jackpot: eins zu hundertvierzig Millionen.": "A hipótese de acertar no jackpot: uma em cento e quarenta milhões.",
  "Vom Blitz getroffen zu werden ist wahrscheinlicher.": "É mais provável levares com um raio.",
