  // ── Star signs: typical Capricorn, and Mercury is in retrograde (part241) ──
  //
  // The signs take their Portuguese names, and two of them are where Portugal
  // and Brazil part: Aries is Carneiro and Libra is Balança here, not Áries
  // and Libra. Getting those two wrong would put a Brazilian newspaper on the
  // breakfast table.
  //
  // Smalltalk is conversa de circunstância, the talk you make because someone
  // is standing there. And Sag nie: Das ist doch Unsinn is advice about not
  // being rude, so the Portuguese takes the quotation marks off and keeps the
  // advice: nunca digas que aquilo é um disparate.
  "das Sternzeichen": "o signo",
  "das Horoskop": "o horóscopo",
  "der Steinbock": "Capricórnio",
  "der Stier": "Touro",
  "der Widder": "Carneiro",
  "der Wassermann": "Aquário",
  "die Jungfrau": "Virgem",
