  "Welches Sternzeichen bist du? — Steinbock.": "De que signo és? — Capricórnio.",
  "Ich bin Waage — angeblich immer auf der Suche nach Balance.": "Sou Balança — dizem que ando sempre à procura de equilíbrio.",
  "Anfang August geboren, also Löwe.": "Nascida no início de agosto, portanto Leão.",
