  "Für den Aszendenten braucht man die genaue Uhrzeit der Geburt.": "Para o ascendente é preciso saber a hora exata do nascimento.",
  "Zwei Stiere in einer Beziehung — das wird stur.": "Dois Touros na mesma relação — vai ser teimosia a dobrar.",
  "Typisch Jungfrau: alles ordentlich, alles geplant.": "Típico de Virgem: tudo arrumado, tudo planeado.",
  "Skorpione vergessen angeblich nie etwas.": "Dizem que os Escorpiões nunca se esquecem de nada.",
  "Der Schütze braucht Freiheit, sagt man.": "O Sagitário precisa de liberdade, dizem.",
