  "Mein Tageshoroskop rät mir heute zu Geduld.": "O meu horóscopo do dia aconselha-me hoje paciência.",
  "Das Horoskop steht auf der letzten Seite der Zeitschrift.": "O horóscopo vem na última página da revista.",
  "Beim Frühstück lese ich zuerst das Horoskop vor.": "Ao pequeno-almoço, a primeira coisa que leio em voz alta é o horóscopo.",
  "Lies meins auch vor! — Du glaubst doch nicht dran.": "Lê o meu também! — Ora, tu nem sequer acreditas nisso.",
  "Heute günstig: Finanzen. Na dann.": "Hoje favorável: finanças. Ora bem.",
  "Am Jahresanfang lesen alle das Jahreshoroskop.": "No início do ano toda a gente lê o horóscopo do ano.",
  "Horoskope sind so geschrieben, dass sie auf alle zutreffen.": "Os horóscopos são escritos de maneira a aplicarem-se a toda a gente.",
  "Irgendwas trifft immer zu — das ist der Trick.": "Há sempre uma coisa que bate certo — o truque é esse.",
  "Trotzdem stimmt meins diese Woche erstaunlich oft.": "Mesmo assim, esta semana o meu tem acertado imenso.",
  "Sie nimmt ihr Horoskop ernster, als sie zugibt.": "Ela leva o horóscopo mais a sério do que admite.",
  "Ich lese es aus Spaß, nicht aus Überzeugung.": "Leio por brincadeira, não por convicção.",
  "Merkur ist rückläufig — daran liegt es bestimmt.": "Mercúrio está retrógrado — de certeza que é disso.",
  "Wenn etwas schiefgeht: Merkur war es.": "Sempre que corre alguma coisa mal: a culpa é de Mercúrio.",
  "Das Sternbild am Himmel hat mit dem Horoskop wenig zu tun.": "A constelação que está no céu pouco tem a ver com o horóscopo.",
  "Die Deutung ist frei — und genau das macht den Spaß.": "A interpretação fica ao critério de cada um — e é precisamente aí que está a graça.",
  "Sternzeichen sind Smalltalk, der immer funktioniert.": "Os signos são conversa de circunstância que resulta sempre.",
  "Beim ersten Date kommt die Frage garantiert.": "Num primeiro encontro a pergunta aparece de certeza.",
  "Sag nie: Das ist doch Unsinn — lächle einfach.": "Nunca digas que aquilo é um disparate — sorri e pronto.",
  "Welches Sternzeichen bist du eigentlich?": "Afinal, de que signo és tu?",
