  "Hm ... Jungfrau? Dein Schreibtisch ist verdächtig ordentlich.": "Hm... Virgem? A tua secretária está arrumada de mais para ser normal.",
  "Treffer. Und jetzt sag nicht: typisch.": "Acertaste. E agora não vás dizer que é típico.",
  "Lies mir mein Horoskop vor.": "Lê-me lá o meu horóscopo.",
