  // ── The car pool: fuel money, who picks the music, silence before eight (part242) ──
  //
  // Boleia is the word the whole pack hangs on, and it is European Portuguese
  // and nothing else — Brazil says carona. Quatschen is dar à língua, and
  // tanken is atestar, which is what a Portuguese driver says at the pump.
  //
  // Wer fährt, bestimmt die Musik is a house rule, so it keeps the shape of a
  // house rule: quem conduz manda na música. And the German morning silence
  // is friendly, not sullen — ficamos calados, mas de boa vontade.
  "die Fahrgemeinschaft": "a boleia partilhada",
  "die Mitfahrgelegenheit": "a boleia",
  "das Spritgeld": "o dinheiro da gasolina",
  "der Mitfahrer": "o passageiro",
  "abwechselnd": "à vez",
  "der Treffpunkt": "o ponto de encontro",
  "der Sprit": "a gasolina",
  "das Autoradio": "o rádio do carro",
  "die Route": "o percurso",
  "einsammeln": "ir buscar",
  "der Umweg": "o desvio",
  "quatschen": "dar à língua",
  "die Rückbank": "o banco de trás",
  "zusteigen": "entrar pelo caminho",
  "das Handschuhfach": "o porta-luvas",
  "Wollen wir eine Fahrgemeinschaft gründen? Wir wohnen ja fast nebeneinander.": "E se combinássemos ir no mesmo carro? Vivemos praticamente porta com porta.",
  "Ich fahre Montag und Mittwoch, du den Rest.": "Eu conduzo à segunda e à quarta, tu o resto.",
  "Wir fahren abwechselnd, jede Woche wechselt es.": "Vamos à vez, muda todas as semanas.",
  "Treffpunkt ist um sieben am Parkplatz beim Bäcker.": "O ponto de encontro é às sete no parque da padaria.",
  "Wer zuerst da ist, holt die Brötchen.": "Quem chega primeiro traz o pão.",
  "Ich sammle euch der Reihe nach ein.": "Vou-vos buscar um a um, pela ordem.",
  "Kannst du mich morgen mitnehmen? Mein Auto ist in der Werkstatt.": "Podes dar-me boleia amanhã? O meu carro está na oficina.",
  "Ich nehme dich mit, steig einfach vorne ein.": "Levo-te, entra à frente.",
  "Rutsch mal rüber, auf der Rückbank ist noch Platz.": "Chega-te lá para o lado, ainda há lugar no banco de trás.",
  "Zusteigen geht auch an der Haltestelle, wenn dir das lieber ist.": "Se preferires, também podes entrar na paragem.",
  "Bei uns gilt: Wer fährt, bestimmt die Musik.": "A regra aqui é: quem conduz manda na música.",
  "Das Autoradio läuft morgens leise — vor dem Kaffee wird nicht diskutiert.": "De manhã o rádio vai baixinho — antes do café não se discute.",
  "Auf der Fahrt wird gequatscht oder geschwiegen — beides ist okay.": "Durante a viagem ou se dá à língua ou se está calado — as duas coisas servem.",
  "Morgens schweigen wir uns freundlich an.": "De manhã ficamos calados, mas de boa vontade.",
  "Der Umweg über dein Dorf kostet nur fünf Minuten.": "O desvio pela tua aldeia só custa cinco minutos.",
  "Ohne Stau sind wir in zwanzig Minuten da.": "Sem trânsito chegamos lá em vinte minutos.",
  "Im Stau ist Gesellschaft Gold wert.": "Numa fila de trânsito, a companhia vale ouro.",
  "Die Route ändern wir nur, wenn alle einverstanden sind.": "O percurso só se muda se todos concordarem.",
  "Beim Spritgeld machen wir es einfach: zehn Euro die Woche.": "O dinheiro da gasolina fazemos assim, simples: dez euros por semana.",
  "Das Spritgeld legen wir ins Handschuhfach.": "O dinheiro da gasolina fica no porta-luvas.",
  "Bei den Spritpreisen rechnet sich jede geteilte Fahrt.": "Com a gasolina ao preço que está, qualquer viagem partilhada compensa.",
  "Getankt wird abwechselnd, das gleicht sich aus.": "Cada um atesta à sua vez, no fim dá tudo certo.",
  "Wer krank ist, sagt bis sechs Uhr Bescheid.": "Quem estiver doente avisa até às seis.",
  "Zur Not springt der Zug ein.": "Se for preciso, há sempre o comboio.",
  "Für lange Strecken gibt es Mitfahrgelegenheiten online.": "Para viagens longas há boleias na internet.",
  "Die Mitfahrgelegenheit nach Berlin kostet fünfzehn Euro.": "A boleia para Berlim custa quinze euros.",
  "Mit fremden Mitfahrern hat man die besten Gespräche.": "É com desconhecidos no carro que se têm as melhores conversas.",
  "Eine Fahrgemeinschaft spart Geld, Nerven und einen Parkplatz.": "Ir no mesmo carro poupa dinheiro, paciência e um lugar de estacionamento.",
  "Wir fahren doch beide jeden Tag nach Mainz.": "Afinal vamos os dois todos os dias a Mainz.",
  "Stimmt. Fahrgemeinschaft?": "É verdade. Vamos no mesmo carro?",
  "Du Montag und Mittwoch, ich den Rest?": "Tu à segunda e à quarta, eu o resto?",
  "Und das Spritgeld rechnen wir am Monatsende ab.": "E o dinheiro da gasolina acertamos ao fim do mês.",
  "Morgen! Kaffee steht im Becherhalter.": "Bom dia! O café está no suporte.",
  "Du bist ein Held. Radio leise, ja?": "És um herói. Rádio baixinho, sim?",
  "Wie immer. Vor acht wird nicht geredet.": "Como sempre. Antes das oito não se fala.",
  "Deshalb funktioniert das hier seit drei Jahren.": "É por isso que isto funciona há três anos.",

  // ── The class reunion: name tags, old stories and the hard core (part243) ──
  //
  // Anekdote is not anedota. In Portuguese an anedota is a joke with a
  // punchline, and this pack means the story about the school trip — história.
  // That is a false friend that would have gone unnoticed, because the wrong
  // word is a real word and reads perfectly well.
  //
  // Die mit den Einsen becomes a dos vintes: Portugal marks out of twenty and
  // a vinte is the top of it, so the pupil German remembers by a grade is
  // remembered here by a different number that means the same thing.
  // In Erinnerungen schwelgen is matar saudades, which is the entire evening
  // in two words, and versprochen ist versprochen is o prometido é devido.
