  "Die Einladung kam über die alte Klassengruppe.": "O convite veio pelo grupo antigo da turma.",
  "Unser Jahrgang trifft sich in der alten Aula.": "O nosso ano junta-se no antigo auditório da escola.",
  "Die Schule wirkt viel kleiner als früher.": "A escola parece muito mais pequena do que era.",
  "Namensschilder retten den Abend — seien wir ehrlich.": "Os crachás salvam a noite — sejamos honestos.",
  "Die Ehemaligen kommen aus dem ganzen Land angereist.": "Os antigos alunos vêm de todo o país.",
  "Ich habe dich sofort wiedererkannt!": "Reconheci-te logo!",
  "Manche erkennt man sofort, bei manchen hilft nur das Schild.": "A uns reconhece-se logo, a outros só o crachá é que salva.",
  "Du hast dich kaum verändert!": "Estás na mesma!",
  "Das sagt man so — und meint es sogar halb.": "É o que se diz — e até se acredita um bocado.",
  "Der Klassenlehrer ist auch da — und alle sagen wieder Sie.": "O diretor de turma também veio — e voltam todos a tratá-lo por o senhor.",
  "Er duzt uns jetzt — das fühlt sich immer noch falsch an.": "Agora ele trata-nos por tu — e continua a parecer errado.",
  "Früher warst du der mit den Streichen! — Und du die mit den Einsen.": "Tu eras o das partidas! — E tu a dos vintes.",
  "Aus dem Stillen von damals wurde der Lustigste im Raum.": "O caladinho de então é hoje o mais engraçado da sala.",
  "Einer ist damals sitzengeblieben und heute Chef von allen.": "Um deles chumbou o ano na altura e hoje é chefe de todos.",
  "Weißt du noch, die Klassenfahrt in der Achten?": "Lembras-te da viagem de turma no oitavo ano?",
  "Über die alten Anekdoten lachen wir wie damals.": "Rimo-nos das histórias antigas como naquela altura.",
  "Die Anekdoten werden mit jedem Treffen besser.": "As histórias ficam melhores a cada convívio.",
  "Beim alten Klassenfoto raten wir die Namen durch.": "Diante da fotografia antiga da turma andamos a adivinhar os nomes.",
  "Auf dem Klassenfoto stehe ich wie immer hinten links.": "Na fotografia de turma estou como sempre atrás à esquerda.",
  "In Erinnerungen schwelgen — dafür ist so ein Abend da.": "Matar saudades — é para isso que serve uma noite destas.",
  "Die Schulzeit klingt heute schöner, als sie war.": "O tempo da escola hoje soa melhor do que foi.",
  "Manche Freundschaften machen einfach da weiter, wo sie aufgehört haben.": "Há amizades que pegam exatamente onde ficaram.",
  "Mit manchen verbindet einen nach zwanzig Jahren nichts mehr — auch okay.": "Com alguns, ao fim de vinte anos já não há nada em comum — e não faz mal.",
  "Die Zeit vergeht schneller, als man denkt.": "O tempo passa mais depressa do que a gente pensa.",
  "Nächstes Treffen in fünf Jahren — versprochen ist versprochen.": "Próximo encontro daqui a cinco anos — o prometido é devido.",
  "Die Nummern werden getauscht und nie benutzt.": "Trocam-se os números e nunca mais se usam.",
  "Der harte Kern sitzt am Ende an einem Tisch.": "No fim, os do costume ficam todos à mesma mesa.",
  "Zwanzig Jahre! Kommst du zum Klassentreffen?": "Vinte anos! Vais ao convívio de turma?",
  "Ich weiß nicht ... wen erkenne ich da noch?": "Não sei... quem é que eu ainda vou reconhecer?",
