  // ── The language course: placement test, level B1, the exam (part245) ──
  //
  // The Volkshochschule keeps its name. It is a German institution with a
  // desk and an enrolment form, and somebody signing up has to say the word
  // to the person behind it — the same reason the Bürgeramt keeps its name.
  //
  // Arbeitsblatt is a ficha de trabalho, which is what a Portuguese teacher
  // hands out, and mit Händen und Füßen is not about hands and feet but about
  // gesticulating until it lands: à força de gestos.
  "der Sprachkurs": "o curso de línguas",
  "der Einstufungstest": "o teste de nivelamento",
  "das Niveau": "o nível",
  "das Zertifikat": "o certificado",
  "die Kursleiterin": "a professora do curso",
  "der Integrationskurs": "o curso de integração",
  "die Volkshochschule": "a Volkshochschule",
  "der Konversationskurs": "o curso de conversação",
  "die Lektion": "a unidade",
  "das Arbeitsblatt": "a ficha de trabalho",
  "teilnehmen": "participar",
  "die Muttersprache": "a língua materna",
