  "An der Volkshochschule sind die Kurse günstig.": "Na Volkshochschule os cursos são baratos.",
  "Vorher machst du einen Einstufungstest.": "Antes fazes um teste de nivelamento.",
  "Der Test sagt: Niveau B1. Ich hätte auf A2 getippt.": "O teste diz: nível B1. Eu apostava no A2.",
  "Auf welchem Niveau bist du gerade?": "Em que nível é que estás neste momento?",
  "Der Integrationskurs ist für viele Pflicht.": "Para muita gente o curso de integração é obrigatório.",
  "Der Kurs läuft zweimal die Woche, abends.": "O curso é duas vezes por semana, à noite.",
  "In meinem Kurs sitzen zwölf Nationen an einem Tisch.": "Na minha turma há doze nacionalidades à volta da mesma mesa.",
  "Unsere Kursleiterin spricht im Unterricht nur Deutsch.": "A nossa professora só fala alemão nas aulas.",
  "Sie erklärt die Grammatik mit Händen und Füßen.": "Ela explica a gramática à força de gestos.",
  "Heute machen wir Lektion sieben: Perfekt und Präteritum.": "Hoje damos a unidade sete: os dois tempos do passado.",
  "Die Arbeitsblätter sammeln sich in meinem Ordner.": "As fichas de trabalho vão-se acumulando no meu dossiê.",
  "Im Konversationskurs reden wir einfach — ohne Buch.": "No curso de conversação limitamo-nos a falar — sem livro.",
  "Wir üben zu zweit, dann wechseln wir die Partner.": "Praticamos aos pares e depois trocamos de par.",
  "Die Hausaufgaben gebe ich meistens zu spät ab.": "Os trabalhos de casa entrego-os quase sempre atrasados.",
  "Fehler machen gehört dazu — sonst lernt man nichts.": "Errar faz parte — senão não se aprende nada.",
  "Sie korrigiert nur die Fehler, die wichtig sind.": "Ela só corrige os erros que interessam.",
  "Nach drei Monaten merke ich echten Fortschritt.": "Ao fim de três meses noto progressos a sério.",
  "In meiner Muttersprache wäre das ein Satz — auf Deutsch drei.": "Na minha língua materna isso era uma frase — em alemão são três.",
  "Am Anfang habe ich fast nichts verstanden.": "No início não percebia quase nada.",
  "Jetzt träume ich manchmal schon auf Deutsch.": "Agora já sonho às vezes em alemão.",
  "Regelmäßig üben bringt mehr als ein langes Wochenende.": "Praticar com regularidade rende mais do que um fim de semana inteiro.",
  "Nimm am Konversationsabend teil, das kostet nichts.": "Participa na noite de conversação, não custa nada.",
  "Für die Prüfung brauche ich das Zertifikat B1.": "Para o exame preciso do certificado B1.",
  "Die Prüfung hat vier Teile: Hören, Lesen, Schreiben, Sprechen.": "O exame tem quatro partes: compreensão oral, leitura, escrita e oralidade.",
  "Beim Sprechen sitzt man zu zweit vor der Prüferin.": "Na parte oral ficam dois à frente da examinadora.",
  "Bestanden! Das Zertifikat kommt in zwei Wochen per Post.": "Passei! O certificado chega pelo correio dentro de duas semanas.",
  "Und jetzt: der nächste Kurs, B2.": "E agora: o curso a seguir, o B2.",
  "Sie machen zuerst einen Einstufungstest.": "Primeiro faz um teste de nivelamento.",
  "Muss ich dafür lernen?": "Tenho de estudar para isso?",
  "Nein, er zeigt nur, welcher Kurs zu Ihnen passt.": "Não, serve só para mostrar que curso é o mais indicado para si.",
