  // ── Streaming: one more episode, then that's really it (part246) ────────
  //
  // Two words here are where Portugal and Brazil visibly part: dubbed is
  // dobrado, not dublado, and the settings menu is definições, not
  // configurações. Both are the kind of word somebody reads off a screen
  // every evening, so getting them wrong would be noticed immediately.
  //
  // The remote is o comando — one word, and the only one a Portuguese hand
  // reaches for under the cushion.
