  "Bei offenem Fenster schlafe ich am besten.": "Durmo melhor com a janela aberta.",
  "Vor dem Schlafen noch einmal kurz lüften.": "Antes de dormir, arejar mais uma vez um bocadinho.",
  "An der Zeitumstellung leide ich jedes Mal.": "A mudança da hora dá-me sempre cabo de mim.",
  "Im Frühjahr fehlt uns eine Stunde Schlaf.": "Na primavera falta-nos uma hora de sono.",
  "Im Herbst bekommen wir sie zurück — das ist die schöne Umstellung.": "No outono devolvem-na — essa é a mudança boa.",
  "Die Kinder merken von der Umstellung nichts — sie stehen trotzdem um sechs auf.": "Os miúdos não dão pela mudança nenhuma — levantam-se às seis na mesma.",
  "Steh auf, Schlafmütze!": "Levanta-te, dorminhoco!",
  "Gut geschlafen? — Wie ein Stein.": "Dormiste bem? — Como uma pedra.",
  "Du siehst müde aus.": "Tens ar de cansado.",
  "Ich war ab drei wach und dann hellwach.": "Acordei às três e depois fiquei completamente desperto.",
  "Wieder das Handy im Bett?": "Outra vez o telemóvel na cama?",
  "Wahrscheinlich. Heute lege ich es raus, versprochen.": "Se calhar. Hoje deixo-o lá fora, prometido.",
  "Wie spät ist es? — Halb elf.": "Que horas são? — Dez e meia.",
  "Herrlich. Endlich mal richtig ausgeschlafen.": "Que maravilha. Finalmente dormi até tarde a sério.",
  "Ich mache Kaffee, du machst Brötchen?": "Eu faço o café, tu tratas do pão?",
  "Abgemacht. Aber ich döse noch fünf Minuten.": "Combinado. Mas ainda dormito mais cinco minutos.",

  // ── Eating well: the ingredients list and the evening craving (part261) ──
  //
  // Die Portion is a dose, which is what Portuguese asks for at a counter and
  // what it freezes leftovers in. Vollkorn is o integral, an adjective doing
  // duty as a noun exactly as it does on a Portuguese bread bag.
  //
  // Verbieten hilft nichts, in Maßen essen schon leans on the schon, which
  // Portuguese cannot echo. It gets the same work out of é que sim, so the
  // second half contradicts the first the way the German does.
  "die Portion": "a dose",
  "zuckerfrei": "sem açúcar",
  "die Diät": "a dieta",
  "der Stoffwechsel": "o metabolismo",
  "das Vollkorn": "o cereal integral",
