  // ── The job interview: strengths, weaknesses and the salary question (part265) ──
  //
  // Portuguese HR has its own fixed phrases and they are the ones on the form:
  // a pretensão salarial, a carta de apresentação, o percurso profissional,
  // candidatar-se. Homeoffice is teletrabalho, one word, and the word the
  // contract uses.
