  "der Werdegang": "o percurso profissional",
  "sich bewerben": "candidatar-se",
  "die Einarbeitung": "a integração",
  "der Wechsel": "a mudança de emprego",
  "belastbar": "resistente à pressão",
  "das Anschreiben": "a carta de apresentação",
  "Ich habe mich auf die Stelle beworben.": "Candidatei-me ao lugar.",
