  "Einverstanden. Und wir reden gut übereinander.": "De acordo. E falamos bem um do outro.",

  // ── Buying a house: the deposit, the notary and the land register (part306) ──
  //
  // Eigenkapital is a entrada — the money you put down, which is what a
  // Portuguese buyer says at the bank counter and not a translation of the
  // German compound. Tilgung is amortização, das Grundbuch is o registo
  // predial, and der Energieausweis is o certificado energético, all of them
  // the exact terms on Portuguese paperwork.
